package com.examforge.question;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.examforge.common.*;import com.examforge.common.ApiDtos.*;import com.examforge.question.entity.QuestionEntity;import com.examforge.question.mapper.QuestionMapper;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.io.*;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Service public class QuestionService{
 private final QuestionMapper mapper;private final ObjectMapper json;public QuestionService(QuestionMapper m,ObjectMapper j){mapper=m;json=j;}
 public PageView<QuestionView>page(long page,long size,String keyword,String type){LambdaQueryWrapper<QuestionEntity>w=new LambdaQueryWrapper<>();if(keyword!=null&&!keyword.isBlank())w.like(QuestionEntity::getContent,keyword);if(type!=null&&!type.isBlank())w.eq(QuestionEntity::getType,type);w.orderByDesc(QuestionEntity::getId);Page<QuestionEntity>p=mapper.selectPage(new Page<>(page,size),w);return new PageView<>(p.getRecords().stream().map(this::view).toList(),p.getTotal(),p.getCurrent(),p.getSize());}
 public QuestionView create(QuestionRequest r,Long userId){QuestionEntity q=from(r);q.setCreatedBy(userId);q.setCreateTime(LocalDateTime.now());q.setUpdateTime(LocalDateTime.now());mapper.insert(q);return view(q);}
 public QuestionView update(Long id,QuestionRequest r){QuestionEntity old=mapper.selectById(id);if(old==null)throw new BusinessException("题目不存在");QuestionEntity q=from(r);q.setId(id);q.setCreatedBy(old.getCreatedBy());q.setCreateTime(old.getCreateTime());q.setUpdateTime(LocalDateTime.now());mapper.updateById(q);return view(q);}
 public void delete(Long id){if(mapper.selectById(id)==null)throw new BusinessException("题目不存在");try{mapper.deleteById(id);}catch(Exception e){throw new BusinessException("该题目已被试卷引用，不能删除");}}
 private QuestionEntity from(QuestionRequest r){if(!Set.of("SINGLE","MULTIPLE","JUDGE","FILL","SUBJECTIVE").contains(r.type()))throw new BusinessException("题型仅支持 SINGLE、MULTIPLE、JUDGE、FILL、SUBJECTIVE");if(!"SUBJECTIVE".equals(r.type())&&(r.correctAnswer()==null||r.correctAnswer().isBlank()))throw new BusinessException("客观题必须设置标准答案");QuestionEntity q=new QuestionEntity();q.setType(r.type());q.setContent(r.content());try{q.setOptionsJson(json.writeValueAsString(r.options()==null?List.of():r.options()));}catch(Exception e){throw new BusinessException("选项格式错误");}q.setCorrectAnswer(r.correctAnswer()==null?"":r.correctAnswer());q.setAnalysis(r.analysis());q.setDifficulty(r.difficulty()==null?"MEDIUM":r.difficulty());q.setKnowledgePoint(r.knowledgePoint());q.setDefaultScore(r.defaultScore()==null?BigDecimal.ONE:r.defaultScore());return q;}
 private QuestionView view(QuestionEntity q){try{return new QuestionView(q.getId(),q.getType(),q.getContent(),json.readValue(q.getOptionsJson()==null?"[]":q.getOptionsJson(),new TypeReference<List<String>>(){}),q.getCorrectAnswer(),q.getAnalysis(),q.getDifficulty(),q.getKnowledgePoint(),q.getDefaultScore());}catch(Exception e){return new QuestionView(q.getId(),q.getType(),q.getContent(),List.of(),q.getCorrectAnswer(),q.getAnalysis(),q.getDifficulty(),q.getKnowledgePoint(),q.getDefaultScore());}}
 @Transactional public ImportResult importExcel(InputStream in,Long userId)throws IOException{int ok=0,skip=0;try(Workbook wb=new XSSFWorkbook(in)){Sheet s=wb.getSheetAt(0);for(int i=1;i<=s.getLastRowNum();i++){Row r=s.getRow(i);if(r==null){skip++;continue;}try{String type=cell(r,0),content=cell(r,1),opts=cell(r,2),answer=cell(r,3);if(type.isBlank()||content.isBlank()||(!"SUBJECTIVE".equals(type)&&answer.isBlank())){skip++;continue;}List<String>options=opts.isBlank()?List.of():json.readValue(opts,new TypeReference<List<String>>(){});QuestionRequest req=new QuestionRequest(type,content,options,answer,cell(r,4),cell(r,5),cell(r,6),new BigDecimal(cell(r,7).isBlank()?"1":cell(r,7)));QuestionEntity q=from(req);q.setCreatedBy(userId);q.setCreateTime(LocalDateTime.now());q.setUpdateTime(LocalDateTime.now());mapper.insert(q);ok++;}catch(Exception e){skip++;}}}return new ImportResult(ok,skip);}
 public byte[]exportExcel()throws IOException{try(Workbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet s=wb.createSheet("题库");String[]h={"type","content","options(JSON)","correctAnswer","analysis","difficulty","knowledgePoint","defaultScore"};Row head=s.createRow(0);for(int i=0;i<h.length;i++)head.createCell(i).setCellValue(h[i]);int n=1;for(QuestionEntity q:mapper.selectList(null)){Row r=s.createRow(n++);r.createCell(0).setCellValue(q.getType());r.createCell(1).setCellValue(q.getContent());r.createCell(2).setCellValue(q.getOptionsJson()==null?"[]":q.getOptionsJson());r.createCell(3).setCellValue(q.getCorrectAnswer());r.createCell(4).setCellValue(q.getAnalysis()==null?"":q.getAnalysis());r.createCell(5).setCellValue(q.getDifficulty()==null?"MEDIUM":q.getDifficulty());r.createCell(6).setCellValue(q.getKnowledgePoint()==null?"":q.getKnowledgePoint());r.createCell(7).setCellValue(q.getDefaultScore().doubleValue());}for(int i=0;i<h.length;i++)s.autoSizeColumn(i);wb.write(out);return out.toByteArray();}}
 private String cell(Row r,int i){Cell c=r.getCell(i);if(c==null)return "";if(c.getCellType()==CellType.NUMERIC)return BigDecimal.valueOf(c.getNumericCellValue()).stripTrailingZeros().toPlainString();return c.toString().trim();}
}
